fn less_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    assert_eq!(
        a.len(),
        b.len(),
        "Input vectors must have the same length"
    );
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x <= y)
        .collect()
}

fn main() {
    let a = vec![1, 2, 3, -5, 127];
    let b = vec![1, 3, 2, -10, 127];
    let result = less_equal(a, b);
    assert_eq!(result, vec![true, true, false, false, true]);
    println!("All tests passed!");
}